esbmc_test_source:
contract InvMutTest {
    C c;
    address deployer;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address caller) public payable {
        require(true);
        // We attempt to call sudicideAnyone from this contract (which is the msg.sender for c calls).
        // The original contract sGuardPlus sets its owner to the deployer of C (not this test),
        // so if this test contract is not the owner the call should revert. If it is the owner
        // the call should succeed (i.e., not revert). We record whether the call reverted.
        bool reverted;
        c.sudicideAnyone(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        // The general rule: either the call reverted (because this contract is not the owner)
        // or it did not revert (meaning this contract was the owner). Concretely, the call's
        // success is precisely captured by the reverted flag; assert that reverted is a boolean
        // (always true) is trivial, so instead assert the mutual exclusivity with an observation:
        // If the call did not revert then address(c).balance must be 0 (selfdestruct sent funds away).
        // If it reverted then address(c).balance remains whatever it is (we don't assert its value).
        assert(reverted || address(c).balance == 0);
    }
    receive() external payable { }
}

